WITH with_windows AS (SELECT *, NTILE(3) OVER (PARTITION BY store_id, product_id ORDER BY quantity, id) AS quantity_bucket, SUM(quantity) OVER (PARTITION BY store_id) AS store_id_sum_quantity FROM inventory) SELECT product_id, store_id, BIT_AND(quantity) AS quantity_bit_and, BIT_OR(quantity) AS quantity_bit_or, MIN(store_id_sum_quantity) AS min_store_id_sum_quantity FROM with_windows GROUP BY GROUPING SETS ((product_id, store_id), (product_id))
